// Command api serves the todo HTTP API and runs the outbox relay next to it.
// The wiring itself is generated by Wire (wire.go -> wire_gen.go); main only
// picks which graph to build, then runs and stops its two parts.
package main

import (
	"context"
	"fmt"
	"os"
	"os/signal"
	"sync"
	"syscall"

	"github.com/rs/zerolog"

	"example.com/todo/level08/internal/config"
	"example.com/todo/level08/internal/infrastructure/logger"
	"example.com/todo/level08/internal/infrastructure/server"
	providers "example.com/todo/level08/internal/wire"
)

func main() {
	log := logger.New(os.Stdout)
	if err := run(log); err != nil {
		log.Fatal().Err(err).Msg("stopped")
	}
}

func run(log zerolog.Logger) error {
	cfg, err := config.Load()
	if err != nil {
		return err
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	app, cleanup, err := newApp(ctx, cfg, log)
	if err != nil {
		return err
	}
	defer cleanup()
	log.Info().Str("driver", cfg.DBDriver).Msg("storage ready")

	// The relay gets its own ctx, not the signal's: it keeps projecting while the server
	// drains its last requests, and stops only after that.
	relayCtx, stopRelay := context.WithCancel(context.Background())
	var relay sync.WaitGroup
	relay.Go(func() { app.Relay.Run(relayCtx) })

	err = server.Run(ctx, cfg.HTTPAddr, app.Router, log)
	// Wait for the relay to finish its current poll before the deferred cleanup closes
	// the database under it. Unprocessed events stay in the outbox for the next start.
	stopRelay()
	relay.Wait()
	return err
}

// newApp is where the runtime DB_DRIVER meets the compile-time Wire graphs:
// it calls the generated injector for the chosen storage.
func newApp(ctx context.Context, cfg config.Config, log zerolog.Logger) (*providers.App, func(), error) {
	switch cfg.DBDriver {
	case config.DriverPostgres:
		return initPostgresApp(ctx, cfg, log)
	case config.DriverMongo:
		return initMongoApp(ctx, cfg, log)
	default:
		return nil, nil, fmt.Errorf("unknown DB_DRIVER %q", cfg.DBDriver)
	}
}
